  function configureDollarInputs(){document.querySelectorAll('[data-field]').forEach(el=>{const k=el.dataset.field;if(dollarFields.has(k)||k==='gallons'){el.dataset.fullUnits='true';el.type='text';el.inputMode='decimal';el.placeholder=k==='gallons'?'e.g. 10m or 10,000,000':'e.g. 30m or 30,000,000';const label=el.closest('label');for(const node of label?.childNodes||[])if(node.nodeType===3)node.textContent=node.textContent.replace(/\$MM|\$ millions/g,'$ dollars').replace(/, MM|, millions/g,', gallons');}});}
