  function renderSites(){const d=deal();$('#siteRows').innerHTML=d.sites.map((s,i)=>`<tr><td><input data-site="${i}" data-prop="name" value="${esc(s.name||'')}" placeholder="Site / group"></td><td><input data-site="${i}" data-prop="ebitda" type="number" step="any" value="${esc(s.ebitda??'')}" placeholder="—"></td><td><input data-site="${i}" data-prop="gallons" type="number" step="any" value="${esc(s.gallons??'')}" placeholder="—"></td><td><select data-site="${i}" data-prop="route">${['Unassigned','Keep / operate','Dealer / COOP','COAG','CALS','Exit / dispose','Separate valuation'].map(o=>`<option ${s.route===o?'selected':''}>${o}</option>`).join('')}</select></td><td><input data-site="${i}" data-prop="reason" value="${esc(s.reason||'')}" placeholder="Why this route? Rights / rent / cost"></td><td><button data-remove-site="${i}" aria-label="Remove site">×</button></td></tr>`).join('');renderSiteTotal();}
  function renderSiteTotal(){const rows=deal().sites,eb=rows.reduce((s,r)=>s+(present(num(r.ebitda))?num(r.ebitda):0),0),g=rows.reduce((s,r)=>s+(present(num(r.gallons))?num(r.gallons):0),0);$('#siteTotal').textContent=rows.length?`${rows.length} site/group rows · entered EBITDA ${mm(eb)} · entered gallons ${g.toFixed(2)}MM`:'Add a site or a group of similar sites to map the operating routes.';}
