  function calculate(){const m=OriginalModel.calculate(deal()),p=m.inputs,r=m.result,y=r?.years[0],usd=n=>n==null?NaN:n/1e6;return {base:usd(p.base),fuel:usd(y?.fuel),inside:usd(y?.insideBenefit),opex:usd(y?.savings),other:usd(p.otherBenefit),rent:usd(p.addedRent),field:usd(p.fieldCost),dealer:usd(p.operatorCost),buyer:usd(y?.ebitda),ask:usd(p.price),allIn:usd(r?.initial),prior:num(deal().fields.priorEbitda),ttm:num(deal().fields.ttmEbitda),askMult:r?.multiple??NaN,allMult:y?.ebitda>0?r.initial/y.ebitda:NaN,model:m};}
