  const val=(v)=>v&&String(v).trim()?String(v).trim():'Not established';
  function renderBrief(){const d=deal(),f=d.fields,c=calculate();const open=GATES.filter(g=>d.gates[g.id]?.status!=='yes').map(g=>g.title);const evidence=DealEvidence.assess(d,c.model),unresolved=evidence.filter(e=>e.state!=='verified'),received=evidence.filter(e=>['received','verified'].includes(e.state)),outstanding=evidence.filter(e=>['missing','partial'].includes(e.state));const m=c.model,r=m.result;const returnLine=r?`Calculated ${m.inputs.years}-year annual unlevered IRR: ${r.irr==null?'no unique conventional IRR':(r.irr*100).toFixed(1)+'%'}. Target: ${m.inputs.target}%. NPV at target: ${DealModel.money(r.npv)}. Purchase price at target return: ${DealModel.money(r.maxPrice)}. ${Object.values(m.meta).filter(v=>v.status==='estimated').length} estimated inputs require review. Earnings basis: ${m.meta.base.basis}.`:'Model is incomplete: '+m.errors.join('; ')+'.';const siteRows=d.sites.filter(s=>s.name||s.reason);const routeLine=siteRows.length?siteRows.slice(0,8).map(s=>`${s.name||'Unnamed site'} → ${s.route||'Unassigned'}${s.reason?' ('+s.reason+')':''}`).join('; '):'Site-level operating routes have not been assigned.';let changed=present(c.prior)&&present(c.ttm)?`TTM ${mm(c.ttm)} versus prior year ${mm(c.prior)} (${mm(c.ttm-c.prior)} change).`:`TTM/prior-year trend not fully entered.`;const sellerLine=present(num(f.sellerEbitdaUsd))?`Seller table for ${f.sellerTablePeriod||'unconfirmed period'}: revenue ${mm(num(f.sellerRevenueUsd)/1e6)}, gross profit ${mm(num(f.sellerGrossProfitUsd)/1e6)}, expenses ${mm(num(f.sellerExpensesUsd)/1e6)}, EBITDA ${mm(num(f.sellerEbitdaUsd)/1e6)} (seller supplied or reviewed transcription, unverified period and not reconciled to TTM).`:'';const keyRisks=open.length?open.slice(0,4):[];keyRisks.push(...DealEvidence.questions(d,c.model));const baseLabel=d.fieldOrigin?.normEbitda==='ttm proxy'?'TTM proxy (normalization open)':'defensible base';const paper=$('#briefPaper');paper.innerHTML=`<div class="paper-top"><span class="paper-kicker">DEAL LENS / DECISION BRIEF</span><span class="paper-date">${esc(new Date().toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'}))}</span></div><h2>${esc(f.name||'Untitled deal')}</h2>${d.aiReview?`<p class="footnote">AI narrative drafted ${esc(new Date(d.aiReview.time).toLocaleString())}. Review against current figures and any newer materials.</p>`:''}<p class="subhead">${esc(f.market||'Market open')} · ${esc(f.scope||'Scope open')} · ${esc(f.sites||'—')} sites · ${esc(f.stage||'Screening')}</p><div class="decision-bar"><strong>${esc((f.recommendation||'Clarify before pricing').toUpperCase())}</strong><p>${text(val(f.thesis))}</p></div><div class="brief-kpis"><div><span>SELLER ASK</span><strong>${mm(c.ask)}</strong></div><div><span>ASK / BASE EBITDA</span><strong>${mult(c.askMult)}</strong></div><div><span>ALL-IN / RUN-RATE</span><strong>${mult(c.allMult)}</strong></div></div><h3>Why this fits Sunoco</h3><p>${text(val(f.whyUs))}</p><h3>What the business is doing</h3><p>${esc(changed)} ${esc(sellerLine)} ${text(val(f.earningsStory))}</p><h3>Operating choice</h3><p>${esc(routeLine)}</p><h3>Economics and price</h3><p>${baseLabel} ${mm(c.base)}; entered incremental fuel ${mm(c.fuel)}, inside ${mm(c.inside)}, expense ${mm(c.opex)}, dealer/operator allocation ${mm(c.dealer)}; illustrative buyer run-rate ${mm(c.buyer)}. Entered one-time cash needs plus price ${mm(c.allIn)}. ${esc(returnLine)}</p><div class="rule"></div><h3>Downside / deal breaker</h3><p>${text(val(f.downside))}</p><div class="open-items"><h3>Questions before commitment</h3><ul>${(keyRisks.length?keyRisks.slice(0,5):['All seven fit gates marked yes; confirm evidence and model diligence.']).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Evidence received</h3><ul>${(received.length?received.map(e=>e.title+': '+e.label+' — '+e.detail):['No complete source evidence recorded yet.']).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Evidence still needed / incomplete</h3><ul>${(outstanding.length?outstanding.map(e=>e.title+': '+e.detail):['No source categories marked missing; verification may remain open.']).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><h3>Decision requested from Chip</h3><p>${text(val(f.chipAsk))}</p><h3>Next action</h3><p>${text(val(f.nextAction))} · Owner: ${esc(f.actionOwner||'unassigned')} · Due: ${esc(f.actionDue||'not set')}</p><h3>Next three answers</h3><p>${text(val(f.nextAnswers))}</p><p class="footnote">Source/version: ${esc(f.sourceVersion||'Not recorded')} · Evidence items not verified: ${unresolved.length}/${EVIDENCE.length}. Returns use the current forecast and estimates shown in the Model tab. Entries are stored only in this browser.</p>`;}
  const FACT_LABELS={sites:'Site count',ask:'Seller ask / transaction value',priorEbitda:'Prior-year EBITDA',ttmEbitda:'Latest TTM EBITDA',normEbitda:'Normalized EBITDA',gallons:'Annual gallons',insideSales:'Inside sales',opex:'Operating expense'};
  const FACT_KEYS=Object.keys(FACT_LABELS);
  const SITE_LABELS={siteNoiUsd:'Seller site NOI',siteMonthlyGallons:'Monthly site gallons',siteInsideSalesUsd:'Site inside sales',projectedEbitdaUsd:'Projected EBITDA',landlordNoiUsd:'Landlord NOI',fuelDistributionIncomeUsd:'Fuel distribution income',suggestedRentUsd:'Suggested rental income',mortgagePaymentUsd:'Mortgage payment',netIncomeUsd:'Net income',sellerEbitdarUsd:'Seller EBITDAR'};
  const SELLER_LABELS={fuelGrossProfitUsd:'Fuel gross profit',insideGrossProfitUsd:'Inside gross profit',otherIncomeUsd:'Other operating income',rentUsd:'Annual rent',sellerRevenueUsd:'Seller total revenue',sellerCostUsd:'Seller total cost of sales',sellerGrossProfitUsd:'Seller total gross profit',sellerExpensesUsd:'Seller total expenses',sellerEbitdaUsd:'Seller table EBITDA'};
  let selectedFiles=[],pendingUploadDealId='',fileSelectionEpoch=0;
