  function switchTab(tab){document.querySelectorAll('.panel').forEach(el=>el.classList.toggle('active',el.id===tab));document.querySelectorAll('.nav-btn').forEach(el=>el.classList.toggle('active',el.dataset.tab===tab));$('#crumb').textContent=({tracker:'DEAL TRACKER',intake:'DEAL INTAKE',fit:'STRATEGIC FIT',plan:'DEAL PLAN',numbers:'ECONOMICS',brief:'BRIEF FOR CHIP'})[tab];window.scrollTo({top:0,behavior:'smooth'});}
  document.addEventListener('input',e=>{const t=e.target;if(t.id==='readingMethod')return;if(t.id==='pastedAiResponse'){deal().pasteDraft=t.value;save();return;}if(t.id==='rawDealText'){deal().draftNote=t.value;save();refreshPastePrompt();return;}if(t.dataset.field){const aliases={ask:'price',normEbitda:'base',ttmEbitda:'base',sites:'sites',gallons:'gallons',insideSales:'inside',opex:'opex',fuelCpg:'fuelBenefit',insidePts:'insideLift',opexPct:'savings',otherBenefit:'otherBenefit',rentCost:'addedRent',fieldCost:'fieldCost',dealerCost:'operatorCost',liabilities:'unams',workingCapital:'workingCapital',conversion:'initialCapex',tanks:'environmental',targetIrr:'target'};const modelKey=aliases[t.dataset.field];if(modelKey){delete (deal().modelInputs||={})[modelKey];delete (deal().originalInputs||={})[modelKey];delete (deal().modelConfirmed||={})[modelKey];}deal().fields[t.dataset.field]=storedField(t);(deal().fieldOrigin ||= {})[t.dataset.field]='manual';if(t.dataset.field==='ttmEbitda'&&deal().fieldOrigin.normEbitda==='ttm proxy')deal().fields.normEbitda=storedField(t);save();if(t.dataset.field==='name')renderPicker();renderTracker();renderAction();renderNumbers(false);renderBrief();if(!t.closest('#tableReviewCard'))renderIntake();}else if(t.dataset.gateNote){(deal().gates[t.dataset.gateNote] ||= {}).note=t.value;save();renderBrief();}else if(t.dataset.evidenceSource){(deal().evidence[t.dataset.evidenceSource] ||= {}).source=t.value;save();renderBrief();}else if(t.dataset.factEdit){const v=num(t.value);if(present(v)){const d=deal(),key=t.dataset.factEdit;d.fields[key]=String(v);(d.fieldOrigin ||= {})[key]='manual';if(key==='ttmEbitda'&&d.fieldOrigin.normEbitda==='ttm proxy')d.fields.normEbitda=String(v);autoNarrative(d);save();renderNumbers();renderBrief();t.closest('.fact').querySelector('.fact-value').textContent=factFormat(key,v);t.closest('.fact').querySelector('.saved').textContent='Your correction';}}else if(t.dataset.site!=null){deal().sites[Number(t.dataset.site)][t.dataset.prop]=t.value;save();renderSiteTotal();renderBrief();}});
  document.addEventListener('change',e=>{const t=e.target;if(t.dataset.gate){(deal().gates[t.dataset.gate] ||= {}).status=t.value;save();renderGates();renderBrief();}else if(t.dataset.task){deal().tasks[t.dataset.task]=t.checked;save();renderPhases();}else if(t.dataset.evidence){(deal().evidence[t.dataset.evidence] ||= {}).status=t.value;save();renderEvidence();renderNeeds(deal());renderBrief();}else if(t.dataset.site!=null){deal().sites[Number(t.dataset.site)][t.dataset.prop]=t.value;save();renderBrief();}});
  document.addEventListener('focusout',e=>{if(e.target.dataset.factEdit||e.target.closest('#tableReviewCard')){autoNarrative(deal());renderIntake();renderBrief();}});
  document.querySelectorAll('.nav-btn').forEach(b=>b.addEventListener('click',()=>switchTab(b.dataset.tab)));
  $('#dealPicker').addEventListener('change',e=>{db.active=e.target.value;$('#intakeStatus').textContent='Saved deal loaded';selectedFiles=[];$('#dealFiles').value='';$('#fileQueue').textContent='No files selected';$('#fileResults').innerHTML='';$('#rawDealText').value='';save();hydrate();});
  $('#dealFiles').addEventListener('change',async e=>{
    const files=[...e.target.files];
    if(files.length&&document.querySelector('[name="uploadIntent"]:checked')?.value==='new'&&DealIntake.hasData(deal()))startNewDeal('New deal');
    selectedFiles=files;pendingUploadDealId=deal().id;const epoch=++fileSelectionEpoch,d=deal();
    $('#fileQueue').textContent=files.length?files.map(f=>`${f.name} (${(f.size/1048576).toFixed(1)} MB)`).join(' · '):'No files selected';
    refreshPastePrompt();$('#pasteStatus').textContent='Attach these same files in your AI chat, then paste the readable response.';
    for(const file of files.filter(f=>/\.xlsx$/i.test(f.name))){
      try{
        const read=await DealParser.parseFile(file);if(epoch!==fileSelectionEpoch||deal().id!==d.id)return;
        if(read.roster?.length){
          DealRoster.merge(d,read.roster);const count=d.sites.filter(s=>s.address).length,counts=DealRoster.counts(d.sites);
          DealIntake.remember(d,[{key:'sites',value:counts.sites||count,scope:'portfolio',source:read.roster[0].source,confidence:'medium',excerpt:'Retail site count from asset roster'},{key:'assetCount',value:count,scope:'portfolio',source:read.roster[0].source,confidence:'medium',excerpt:'Counted all named asset roster rows with addresses'}]);
          if(d.fieldOrigin?.sites!=='manual'){d.fields.sites=String(counts.sites||count);(d.fieldOrigin||={}).sites='local asset roster';}
          (d.materials||=[]).unshift({name:file.name,time:new Date().toISOString(),state:'Asset roster read locally',detail:read.roster.length+' rows with addresses · no API charge'});
          (d.history||=[]).unshift({time:new Date().toISOString(),label:'Asset roster received',detail:read.roster.length+' asset rows · read locally from '+file.name,kinds:['asset roster']});
          save();hydrate();$('#pasteStatus').textContent=count+' asset rows received locally. Paste the AI financial summary to fill the model. No API charge.';
        }
      }catch(error){if(epoch===fileSelectionEpoch)$('#pasteStatus').textContent='Local roster read: '+error.message+' You can still paste the readable AI summary and site table.';}
    }
  });
  $('#analyzeDeal').addEventListener('click',processMaterials);
  document.addEventListener('change',e=>{const t=e.target;if(!t.dataset.factEdit)return;const v=num(t.value);if(!present(v)){toast('Enter a number to correct this fact');return;}const d=deal(),key=t.dataset.factEdit;d.fields[key]=String(v);(d.fieldOrigin ||= {})[key]='manual';if(key==='ttmEbitda'&&d.fieldOrigin.normEbitda==='ttm proxy')d.fields.normEbitda=String(v);autoNarrative(d);save();hydrate();toast(`${FACT_LABELS[key]} corrected`);});
  document.addEventListener('click',e=>{const b=e.target.closest('[data-adopt-key]');if(!b)return;const d=deal(),key=b.dataset.adoptKey;d.fields[key]=b.dataset.adoptValue;(d.fieldOrigin ||= {})[key]='selected source';if(key==='ttmEbitda'&&d.fieldOrigin.normEbitda==='ttm proxy')d.fields.normEbitda=b.dataset.adoptValue;autoNarrative(d);save();hydrate();toast(`${FACT_LABELS[key]} updated from source`);});
  $('#newDeal').addEventListener('click',()=>startNewDeal());
