  $('#exportDeal').addEventListener('click',()=>{const d=deal();const blob=new Blob([JSON.stringify({format:'deal-lens-v1',exported:new Date().toISOString(),deal:d},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=(d.fields.name||'deal').replace(/[^a-z0-9-]+/gi,'-').replace(/^-|-$/g,'').toLowerCase()+'-deal-lens.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);$('#moreMenu').hidden=true;toast('Deal backup downloaded');});
