  $('#importFile').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{const imported=JSON.parse(await file.text());if(imported.format!=='deal-lens-v1'||!imported.deal||typeof imported.deal.fields!=='object'||!Array.isArray(imported.deal.sites))throw Error('Invalid backup');const d=imported.deal;d.id=id();d.fields.name=(d.fields.name||'Imported deal')+' (imported)';d.gates=d.gates||{};d.tasks=d.tasks||{};d.evidence=d.evidence||{};db.deals.push(d);db.active=d.id;save();hydrate();switchTab('intake');toast('Deal imported');}catch{toast('Could not import this Deal Lens backup');}e.target.value='';});
  $('#deleteDeal').addEventListener('click',()=>{if(!confirm(`Delete ${deal().fields.name||'this deal'} from this browser? Export a backup first if needed.`))return;db.deals=db.deals.filter(d=>d.id!==db.active);if(!db.deals.length)db.deals=[blank()];db.active=db.deals[0].id;save();hydrate();$('#moreMenu').hidden=true;toast('Deal removed from this browser');});
  $('#copyBrief').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('#briefPaper').innerText);toast('Brief copied');}catch{toast('Copy unavailable; use Print / PDF');}});
